typedef struct { const char *name; const char *city; } Person;

static Person person_with_city(Person p, const char *city) {
    Person out = p;          /* shallow copy of every member */
    out.city = city;         /* only this member differs   */
    return out;
}

struct person_lens {         /* hand-written per-type lens */
    const char *(*get)(const Person *);
    Person      (*set)(Person, const char *);
};
